package io.github.diodeme.ji.agent.core;

import io.github.diodeme.ji.agent.AgentRuntime;
import io.github.diodeme.ji.agent.AgentSession;
import io.github.diodeme.ji.agent.RuntimeConfiguration;
import io.github.diodeme.ji.agent.SessionOptions;
import io.github.diodeme.ji.error.ErrorCode;
import io.github.diodeme.ji.error.JiError;
import io.github.diodeme.ji.error.JiException;
import io.github.diodeme.ji.session.tree.SessionDocument;
import java.util.Map;
import java.util.Optional;
import java.util.OptionalLong;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CompletionStage;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicBoolean;

final class CoreAgentRuntime implements AgentRuntime {
    private final RuntimeConfiguration configuration;
    private final boolean ownsExecutor;
    private final ToolBatchScheduler toolScheduler;
    private final Map<String, CoreAgentSession> sessions = new ConcurrentHashMap<>();
    private final AtomicBoolean closed = new AtomicBoolean();

    CoreAgentRuntime(RuntimeConfiguration configuration, boolean ownsExecutor) {
        this.configuration = configuration;
        this.ownsExecutor = ownsExecutor;
        this.toolScheduler = new ToolBatchScheduler(configuration.toolExecutionPolicy(),
                configuration.permissionDecider(), configuration.toolInterceptors(),
                configuration.executor(), configuration.clock());
    }

    @Override
    public AgentSession newSession(SessionOptions options) {
        requireOpen();
        String sessionId = configuration.idGenerator().next("session");
        SessionDocument document = configuration.sessionRepository().create(
                sessionId, options.model(), options.workingDirectory(), configuration.clock().instant());
        return sessions.computeIfAbsent(sessionId, ignored -> new CoreAgentSession(configuration, document, toolScheduler));
    }

    @Override
    public AgentSession loadSession(String sessionId) {
        requireOpen();
        return sessions.computeIfAbsent(sessionId, ignored -> configuration.sessionRepository().load(sessionId)
                .map(this::recoverAfterRestart)
                .map(document -> new CoreAgentSession(configuration, document, toolScheduler))
                .orElseThrow(() -> new JiException(new JiError(ErrorCode.SESSION_NOT_FOUND,
                        Map.of("sessionId", sessionId), Optional.empty(), Optional.empty(), OptionalLong.empty()))));
    }

    private SessionDocument recoverAfterRestart(SessionDocument document) {
        SessionDocument paused = document.pauseAfterRestart();
        if (paused == document) return document;
        return configuration.sessionRepository().update(
                document.metadata().sessionId(), document.revision(), current -> current.pauseAfterRestart());
    }

    @Override
    public io.github.diodeme.ji.session.tree.SessionRepository sessionRepository() {
        requireOpen();
        return configuration.sessionRepository();
    }

    @Override
    public CompletionStage<Void> closeAsync() {
        if (!closed.compareAndSet(false, true)) return CompletableFuture.completedFuture(null);
        sessions.values().forEach(CoreAgentSession::close);
        toolScheduler.close();
        configuration.provider().close();
        configuration.sessionRepository().close();
        if (ownsExecutor) configuration.executor().close();
        return CompletableFuture.completedFuture(null);
    }

    private void requireOpen() {
        if (closed.get()) throw new JiException(new JiError(ErrorCode.RUNTIME_CLOSED,
                Map.of("resource", "agent-runtime"), Optional.empty(), Optional.empty(), OptionalLong.empty()));
    }
}
